const angleLabels={front:'全身正面',portrait:'正面半身大头像',left:'单个90°侧面 · 朝画面左 ←',right:'右侧 · 朝画面右 →',back:'背面 · 背对镜头'};
function activeMulti(c){return c?.multi?.[c.multiActive??(c.multi.length-1)];}
function angleHistory(entry,angle){entry.angle_history??={};entry.angle_history[angle]??=[];return entry.angle_history[angle];}
async function regenerateAngle(c,angle){if(!validImageSize(c)||[...document.querySelectorAll('[data-image-size]')].some(i=>!i.checkValidity())){toast('请先修正生成尺寸');return}const currentFront=selectedFront(c);if(!c.confirmed||c.confirmedVersion!==c.active||!currentFront?.job_id){toast('请先确认当前正面图，再生成其他角度');return}const referenceJobId=currentFront.job_id;let entry=activeMulti(c);if(!entry?.reference_job_id){const source=selectedFront(c);if(!c.confirmed||c.confirmedVersion!==c.active||!source?.job_id){toast('请先确认正面图');return}entry={time:new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'}),prompt:c.multiPrompt,reference_job_id:source.job_id,jobs:{}};c.multi??=[];c.multi.push(entry);c.multiActive=c.multi.length-1;}if(entry.reference_job_id!==referenceJobId){entry.previous_reference_job_id=entry.reference_job_id;entry.reference_job_id=referenceJobId;}entry.jobs??={};if(multiBusyStates.includes(entry.jobs[angle]?.status)){toast('这个角度正在生成，请等待完成');return}const old=entry.jobs[angle];if(old?.id&&!angleHistory(entry,angle).some(j=>j.id===old.id))angleHistory(entry,angle).unshift(clone(old));const id=crypto.randomUUID(),size={...(c.imageSize||{width:512,height:768})},prompt=c.anglePrompts?.[angle]||c.multiPrompt||entry.prompt;entry.jobs[angle]={id,status:'submitting',angle,reference_job_id:referenceJobId};save();render();try{entry.jobs[angle]=await frontFetch('/api/front-image',{request_id:id,port:Number(localStorage.getItem('frame-comfy-port')||8188),mode:'multiview',angle,reference_job_id:referenceJobId,project_id:data.project_id||data.title,character_id:c.id||c.character_id||c.name,character_name:c.name,background:c.nonWhiteBackground?'gray':'white',prompt,...CharacterSheet.spec.view_sizes[angle]});toast('已单独提交'+angleLabels[angle]);}catch(e){entry.jobs[angle]={id,status:'failed',error:e.message,angle};toast('提交失败：'+e.message)}save();render();}
const anglePromptDialog=document.createElement('dialog');anglePromptDialog.innerHTML='<div class="modal-head"><h2 id="anglePromptTitle">角度提示词</h2><button id="closeAnglePrompt">✕</button></div><p class="subtle">默认沿用多面图提示词。方向要求由工作流额外加入，无需手写；修改只用于这个角度后续生成。</p><textarea id="anglePromptText" rows="8"></textarea><div class="modal-actions"><button id="resetAnglePrompt">沿用通用提示词</button><button id="saveAnglePrompt" class="primary">保存提示词</button></div>';document.body.append(anglePromptDialog);let editingAngle=null;document.querySelector('#closeAnglePrompt').onclick=()=>anglePromptDialog.close();document.querySelector('#saveAnglePrompt').onclick=()=>{if(!editingAngle)return;editingAngle.character.anglePrompts??={};editingAngle.character.anglePrompts[editingAngle.angle]=document.querySelector('#anglePromptText').value;save();anglePromptDialog.close();toast('该角度提示词已保存')};document.querySelector('#resetAnglePrompt').onclick=()=>{if(!editingAngle)return;delete editingAngle.character.anglePrompts?.[editingAngle.angle];document.querySelector('#anglePromptText').value=editingAngle.angle==='front'?editingAngle.character.prompt:editingAngle.character.multiPrompt;save()};
const charactersBeforeSingleAngles=characters;
characters=function(){charactersBeforeSingleAngles();const c=data.characters[ci];if(!c||c.view!=='multi')return;const entry=activeMulti(c);const preview=document.querySelector('#panel .artboard');const boxes=preview?.querySelectorAll('.angle-grid .angle');if(!boxes?.length)return;preview.style.cssText+=';height:auto;min-height:500px';const grid=preview.querySelector('.angle-grid');grid.style.cssText+=';height:auto;align-items:stretch';for(const [i,angle] of ['portrait','front','left','back'].entries()){const box=boxes[i];box.style.cssText+=';display:flex;flex-direction:column;padding-bottom:10px;overflow:visible';const image=box.querySelector('img');if(image)image.style.cssText+=';height:260px;flex:none';const placeholder=box.querySelector('p');if(placeholder)placeholder.style.cssText='height:260px;display:grid;place-items:center;margin:0;padding:15px';if(angle==='front'){frontAngleControls(c,box);continue;}const caption=box.querySelector('span');if(caption)caption.textContent=angleLabels[angle];const controls=document.createElement('div');controls.style.cssText='display:flex;gap:6px;justify-content:center;flex-wrap:wrap;margin:9px 7px 0';const busy=multiBusyStates.includes(entry?.jobs?.[angle]?.status);const button=document.createElement('button');button.textContent=busy?'该角度生成中…':entry?.jobs?.[angle]?'单独重新生成':'仅生成此角度';button.style.cssText='padding:6px 9px;font-size:11px';button.disabled=busy||!(entry?.reference_job_id||(c.confirmed&&selectedFront(c)?.job_id));button.onclick=()=>regenerateAngle(c,angle);const edit=document.createElement('button');edit.textContent='修改提示词';edit.style.cssText='padding:6px 9px;font-size:11px';edit.onclick=()=>{editingAngle={character:c,angle};document.querySelector('#anglePromptTitle').textContent=angleLabels[angle]+' · 提示词';document.querySelector('#anglePromptText').value=c.anglePrompts?.[angle]||c.multiPrompt;anglePromptDialog.showModal()};controls.append(button,edit);const job=entry?.jobs?.[angle];const history=entry?.angle_history?.[angle]||[];if(job&&history.length){const versions=[job,...history.filter(j=>j.id!==job.id)];const select=document.createElement('select');select.setAttribute('aria-label',angleLabels[angle]+'历史版本');select.style.cssText='margin:0;max-width:190px;padding:6px;font-size:10px';select.disabled=busy;versions.forEach((v,index)=>{const option=document.createElement('option');option.value=v.id;option.textContent=(index===0?'当前版本':'历史版本 '+index)+' · '+(v.status==='completed'?'已完成':v.status==='failed'?'失败':'未完成');select.append(option)});select.onchange=()=>{const chosen=versions.find(v=>v.id===select.value);if(!chosen)return;entry.angle_history[angle]=versions.filter(v=>v.id!==chosen.id);entry.jobs[angle]=chosen;c.reference_images??={};if(chosen.image_url)c.reference_images[angle]=chosen.image_url;save();render()};controls.append(select)}box.append(controls)}const main=document.querySelector('#generate');if(main)main.textContent=main.disabled?main.textContent:entry?.jobs?'重新生成整组多面图':'生成整组多面图';};render();

async function regenerateFrontFromPortrait(c){
  if(c.oneClick?.status==='running'){toast('请等待一键生成完成');return;}
  if(multiBusyStates.includes(c.frontJob?.status)){toast('全身正面正在生成，请等待完成');return;}
  const entry=activeMulti(c),portrait=currentIdentityPortrait(c);
  if(portrait?.status!=='completed'||!portrait.id){toast('请先生成正面半身大头像，再重新生成全身正面');return;}
  const prompt=c.anglePrompts?.front||c.prompt;if(!prompt?.trim()){toast('请先填写全身正面提示词');return;}
  const id=crypto.randomUUID();c.frontJob={id,status:'submitting',angle:'front'};save();render();
  try{
    const job=await frontFetch('/api/front-image',{request_id:id,port:Number(localStorage.getItem('frame-comfy-port')||8188),mode:'multiview',angle:'front',reference_job_id:portrait.id,project_id:data.project_id||data.title,character_id:c.id||c.character_id||c.name,character_name:c.name,background:c.nonWhiteBackground?'gray':'white',...CharacterSheet.spec.view_sizes.front,prompt:prompt+'。以参考大头像为唯一人脸身份参考，保持五官、脸型、发型和年龄，补全指定服装、裤子和鞋子。'});
    c.identityPortrait={...portrait};if(entry?.jobs?.portrait?.id===portrait.id)entry.jobs.portrait.identity_master=true;
    applyFrontResult(c,job);toast('已引用大头像提交全身正面，完成后可直接生成其他角度');
  }catch(e){c.frontJob={id,status:'failed',angle:'front',error:e.message};toast('提交失败：'+e.message)}save();render();
}
function frontAngleControls(c,box){
  const controls=document.createElement('div');controls.style.cssText='display:flex;gap:6px;justify-content:center;flex-wrap:wrap;margin:9px 7px 0';
  const busy=multiBusyStates.includes(c.frontJob?.status),portrait=activeMulti(c)?.jobs?.portrait?.status==='completed'?activeMulti(c).jobs.portrait:c.identityPortrait;
  const button=document.createElement('button');button.id='regenerateFullFront';button.textContent=busy?'全身正面生成中…':'单独重新生成';button.disabled=busy||portrait?.status!=='completed';button.title=portrait?.status==='completed'?'引用当前大头像，重新生成512×1440全身正面':'请先生成正面半身大头像';button.onclick=()=>regenerateFrontFromPortrait(c);
  const edit=document.createElement('button');edit.id='editFullFrontPrompt';edit.textContent='修改提示词';edit.onclick=()=>{editingAngle={character:c,angle:'front'};document.querySelector('#anglePromptTitle').textContent='全身正面 · 提示词';document.querySelector('#anglePromptText').value=c.anglePrompts?.front||c.prompt;anglePromptDialog.showModal()};controls.append(button,edit);
  if(c.versions.length>1){const select=document.createElement('select');select.setAttribute('aria-label','全身正面历史版本');select.disabled=busy;c.versions.forEach((v,i)=>{if(!v.job_id||!v.image_url)return;const o=document.createElement('option');o.value=i;o.textContent='正面 V'+(i+1)+(c.active===i?' · 当前':'');select.append(o)});select.value=c.active;select.onchange=()=>{c.active=Number(select.value);c.confirmed=false;c.stale=true;c.reference_images??={};c.reference_images.front=selectedFront(c)?.image_url;save();render()};controls.append(select)}box.append(controls);
}
